const raw = $input.first().json;
if (!raw.choices || !raw.choices[0] || !raw.choices[0].message) {
  throw new Error("Invalid response from OpenRouter: missing choices[0].message");
}

let contentString = raw.choices[0].message.content.trim();
if (contentString.startsWith('```json')) {
  contentString = contentString.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (contentString.startsWith('```')) {
  contentString = contentString.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let articleData = {};
try {
  articleData = JSON.parse(contentString);
} catch (e) {
  const startIdx = contentString.indexOf('{');
  const endIdx = contentString.lastIndexOf('}');
  if (startIdx !== -1 && endIdx !== -1) {
    articleData = JSON.parse(contentString.slice(startIdx, endIdx + 1));
  } else {
    throw new Error("Failed to parse AI JSON response: " + e.message);
  }
}

if (!articleData.title) {
  throw new Error("Validation Failed: generated article missing title");
}

if (!articleData.slug) {
  articleData.slug = articleData.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

if (!articleData.content_html) {
  articleData.content_html = articleData.content || '';
}

// 1. CLEAN BANNED CLICKBAIT WORDS
const bannedTerms = [
  { match: /bikin melongo/gi, replace: 'menarik perhatian publik' },
  { match: /syok berat/gi, replace: 'menjadi sorotan intens' },
  { match: /tak disangka-sangka/gi, replace: 'di luar perkiraan' },
  { match: /lihat apa yang terjadi/gi, replace: 'berikut perkembangannya' },
  { match: /netizen heboh/gi, replace: 'warganet mendiskusikan' }
];
for (const b of bannedTerms) {
  articleData.title = articleData.title.replace(b.match, b.replace);
  articleData.content_html = articleData.content_html.replace(b.match, b.replace);
  if (articleData.excerpt) articleData.excerpt = articleData.excerpt.replace(b.match, b.replace);
}

// 2. DEFENSIVE CHECK: TABLE
if (!articleData.content_html.includes('<table') && Array.isArray(articleData.timeline) && articleData.timeline.length > 0) {
  const tableRows = articleData.timeline.map(t => `
    <tr>
      <td class="border border-slate-700 p-3 font-semibold text-white">${t.time_label || 'Fase'}</td>
      <td class="border border-slate-700 p-3 text-slate-300">${t.event || 'Rekonstruksi data dan jejak digital'}</td>
      <td class="border border-slate-700 p-3 text-neon-cyan font-medium">Terverifikasi</td>
    </tr>`).join('');

  const tableHtml = `
<div class="my-8 overflow-x-auto">
  <table class="w-full border-collapse border border-slate-700 text-left text-sm">
    <thead class="bg-velvet text-white font-semibold">
      <tr>
        <th class="border border-slate-700 p-3">Fase / Periode</th>
        <th class="border border-slate-700 p-3">Kronologi & Rekonstruksi Fakta</th>
        <th class="border border-slate-700 p-3">Status</th>
      </tr>
    </thead>
    <tbody>
      ${tableRows}
    </tbody>
  </table>
</div>`;

  const h2Matches = [...articleData.content_html.matchAll(/<h2/gi)];
  if (h2Matches.length >= 2) {
    const secondH2Index = h2Matches[1].index;
    articleData.content_html = articleData.content_html.slice(0, secondH2Index) + tableHtml + articleData.content_html.slice(secondH2Index);
  } else {
    articleData.content_html += tableHtml;
  }
}

articleData.published_at = new Date().toISOString();

const mainEntity = (articleData.entities && articleData.entities.length > 0) ? articleData.entities[0] : 'Indonesian celebrity';
articleData.caricature_payload = {
  celebrity: mainEntity,
  event: articleData.caricature_event_prompt || articleData.title,
  slug: articleData.slug,
  category: articleData.category || 'seleb-lokal',
  format: 'json'
};

return [{ json: articleData }];
